    for j in range(len(jobs)):
        for o in range(len(jobs[j]) - 1):
            assert mp[(j, o)]["end"] <= mp[(j, o + 1)]["start"], f"Precedence violated: job {j} op{o}->{o+1}"

def test_L1_no_machine_overlap_strict():
