npm start &
SERVER_PID=$!
sleep 5
BEFORE=$(curl -s -o /dev/null -w '%{time_total}' http://localhost:3000)
BEFORE_MS=$(echo "$BEFORE * 1000" | bc | cut -d. -f1)
kill $SERVER_PID 2>/dev/null || true
kill_server

